def test_basico():
    from slugify import slugify
    assert slugify('Hola Mundo') == 'hola-mundo'

def test_guiones():
    from slugify import slugify
    assert slugify('hola__mundo  test') == 'hola-mundo-test'

def test_signos():
    from slugify import slugify
    assert slugify('¡Hola, Mundo!') == 'hola-mundo'

def test_vacio():
    from slugify import slugify
    assert slugify('') == ''

def test_15():
    from fizzbuzz import fizzbuzz
    r = fizzbuzz(15)
    assert r[2] == 'Fizz' and r[4] == 'Buzz' and r[14] == 'FizzBuzz'

def test_1():
    from fizzbuzz import fizzbuzz
    assert fizzbuzz(1) == ['1']

def test_len():
    from fizzbuzz import fizzbuzz
    assert len(fizzbuzz(5)) == 5

def test_basico():
    from wordcount import word_count
    assert word_count('Hola hola mundo') == {'hola': 2, 'mundo': 1}

def test_puntuacion():
    from wordcount import word_count
    assert word_count('hola, mundo! hola.') == {'hola': 2, 'mundo': 1}

def test_vacio():
    from wordcount import word_count
    assert word_count('') == {}

def test_encontrado():
    from bsearch import binary_search
    assert binary_search([1, 3, 5, 7], 5) == 2

def test_primero():
    from bsearch import binary_search
    assert binary_search([1, 3, 5], 1) == 0

def test_ausente():
    from bsearch import binary_search
    assert binary_search([1, 3, 5], 4) == -1

def test_vacia():
    from bsearch import binary_search
    assert binary_search([], 1) == -1

def test_basico():
    from dedup import dedup
    assert dedup([3, 1, 3, 2, 1]) == [3, 1, 2]

def test_vacia():
    from dedup import dedup
    assert dedup([]) == []

def test_sin_dup():
    from dedup import dedup
    assert dedup([1, 2, 3]) == [1, 2, 3]

def test_basico():
    from flatten import flatten
    assert flatten([[1, 2], [3], []]) == [1, 2, 3]

def test_mixto():
    from flatten import flatten
    assert flatten([1, [2, 3], 4]) == [1, 2, 3, 4]

def test_vacia():
    from flatten import flatten
    assert flatten([]) == []

def test_basico():
    from groupby import group_by
    items = [{'t': 'a', 'v': 1}, {'t': 'b', 'v': 2}, {'t': 'a', 'v': 3}]
    g = group_by(items, 't')
    assert [x['v'] for x in g['a']] == [1, 3]
    assert [x['v'] for x in g['b']] == [2]

def test_vacia():
    from groupby import group_by
    assert group_by([], 't') == {}

def test_suma(tmp_path):
    from csvsum import total_por_categoria
    p = tmp_path / 'd.csv'
    p.write_text('categoria,monto\na,10.5\nb,2\na,1.5\n')
    assert total_por_categoria(str(p)) == {'a': 12.0, 'b': 2.0}

def test_solo_header(tmp_path):
    from csvsum import total_por_categoria
    p = tmp_path / 'e.csv'
    p.write_text('categoria,monto\n')
    assert total_por_categoria(str(p)) == {}

