def test_basico():
    from merge_sorted import merge_sorted
    assert merge_sorted([1, 3], [2, 4]) == [1, 2, 3, 4]

def test_vacia():
    from merge_sorted import merge_sorted
    assert merge_sorted([], [1]) == [1]

def test_dup():
    from merge_sorted import merge_sorted
    assert merge_sorted([1, 2], [2, 3]) == [1, 2, 2, 3]
